-- Misma estructura de la base de datos, pero en SQLite (en memoria) para las pruebas unitarias.
CREATE TABLE usuarios (id INTEGER PRIMARY KEY AUTOINCREMENT, correo TEXT NOT NULL UNIQUE, clave_hash TEXT NOT NULL, rol TEXT NOT NULL CHECK (rol IN ('estudiante','empresa','coordinador')), creado_en TEXT NOT NULL);
CREATE TABLE estudiantes (id INTEGER PRIMARY KEY AUTOINCREMENT, usuario_id INTEGER NOT NULL UNIQUE REFERENCES usuarios(id), nombres TEXT NOT NULL, apellidos TEXT NOT NULL, documento TEXT NOT NULL UNIQUE, programa TEXT NOT NULL, semestre INTEGER NOT NULL, telefono TEXT);
CREATE TABLE empresas (id INTEGER PRIMARY KEY AUTOINCREMENT, usuario_id INTEGER NOT NULL UNIQUE REFERENCES usuarios(id), razon_social TEXT NOT NULL, nit TEXT NOT NULL UNIQUE, sector TEXT NOT NULL, ciudad TEXT NOT NULL, contacto TEXT NOT NULL, telefono TEXT);
CREATE TABLE vacantes (id INTEGER PRIMARY KEY AUTOINCREMENT, empresa_id INTEGER NOT NULL REFERENCES empresas(id), titulo TEXT NOT NULL, descripcion TEXT NOT NULL, requisitos TEXT, programa TEXT NOT NULL, modalidad TEXT NOT NULL, cupos INTEGER NOT NULL DEFAULT 1, fecha_cierre TEXT NOT NULL, estado TEXT NOT NULL DEFAULT 'abierta', creado_en TEXT NOT NULL);
CREATE TABLE postulaciones (id INTEGER PRIMARY KEY AUTOINCREMENT, vacante_id INTEGER NOT NULL REFERENCES vacantes(id), estudiante_id INTEGER NOT NULL REFERENCES estudiantes(id), estado TEXT NOT NULL DEFAULT 'enviada', fecha TEXT NOT NULL, UNIQUE (vacante_id, estudiante_id));
